import { normalizeMediaId } from '../utils/mediaId';
import { useEffect, useState } from 'react';
import { useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { api } from '../api';
import MediaDetailsModal from './MediaDetailsModal';
import { BookDetailsModal } from '../pages/Books';
import { loadFallbackBooks, loadFallbackMovies, loadFallbackTvShows } from '../catalogFallback';
import {
  addWatchlistItem,
  fetchRatingMap,
  fetchWatchlist,
  fetchWatchlistStatusMap,
  updateWatchlistStatus,
  saveRating,
} from '../utils/userData';
import {
  fetchBookById,
  fetchMovieById,
  fetchTvShowById,
} from '../utils/catalog';

const CONFIG = {
  movie:    { fetchById: fetchMovieById, apiPath: 'movies',    loadFallback: loadFallbackMovies,  homePath: '/movies' },
  tv_show:  { fetchById: fetchTvShowById, apiPath: 'tv-shows', loadFallback: loadFallbackTvShows, homePath: '/tv-shows' },
  book:     { fetchById: fetchBookById,   apiPath: 'books',    loadFallback: loadFallbackBooks,   homePath: '/books' },
};

// Renders a movie/TV/book details modal as an overlay on top of whatever
// page the user was already on (Home, Profile, search results, etc.),
// instead of navigating to the full Movies/TV Shows/Books catalog page.
// See App.js's background-location routing for how this gets mounted.
export default function MediaOverlay({ mediaType }) {
  const { id } = useParams();
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const location = useLocation();
  const backgroundLocation = location.state?.backgroundLocation;
  const playImmediately = searchParams.get('play') === '1' || searchParams.get('play') === 'true';
  const initialSeason = searchParams.get('season') || undefined;
  const initialEpisode = searchParams.get('episode') || undefined;
  const numericId = normalizeMediaId(id);
  const config = CONFIG[mediaType];

  const [item, setItem] = useState(null);
  const [browseOnly, setBrowseOnly] = useState(false);
  const [userRating, setUserRating] = useState(null);
  const [isInLibrary, setIsInLibrary] = useState(false);
  const [watchlistEntry, setWatchlistEntry] = useState(null);
  const [detailMessage, setDetailMessage] = useState('');
  const [isAddingWatchlist, setIsAddingWatchlist] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setItem(null);
    setBrowseOnly(false);
    setDetailMessage('');

    async function load() {
      try {
        const result = await config.fetchById(numericId);
        if (!cancelled && result?.id) { setItem(result); return; }
      } catch { /* fall through */ }

      try {
        const result = await api.get(`/media/${config.apiPath}/${numericId}`);
        if (!cancelled && result?.id) { setItem(result); return; }
      } catch { /* fall through */ }

      try {
        const items = await config.loadFallback();
        const match = items.find((entry) => entry.id === numericId);
        if (!cancelled && match) { setItem(match); setBrowseOnly(true); }
      } catch { /* ignore missing fallback data */ }
    }

    if (numericId) load();
    return () => { cancelled = true; };
  }, [numericId, config]);

  useEffect(() => {
    let cancelled = false;
    fetchRatingMap(mediaType)
      .then((map) => { if (!cancelled) setUserRating(map?.[numericId] || null); })
      .catch(() => {});
    return () => { cancelled = true; };
  }, [mediaType, numericId]);

  useEffect(() => {
    if (mediaType !== 'book') return undefined;
    let cancelled = false;
    fetchWatchlist({ mediaType: 'book' })
      .then((list) => {
        if (!cancelled) setIsInLibrary((list || []).some((entry) => entry.media_id === numericId));
      })
      .catch(() => {});
    return () => { cancelled = true; };
  }, [mediaType, numericId]);

  useEffect(() => {
    if (mediaType === 'book') return undefined;
    let cancelled = false;
    fetchWatchlistStatusMap(mediaType)
      .then((map) => { if (!cancelled) setWatchlistEntry(map[numericId] || null); })
      .catch(() => {});
    return () => { cancelled = true; };
  }, [mediaType, numericId]);

  function goBack() {
    if (backgroundLocation) navigate(-1);
    else navigate(config.homePath);
  }

  async function handleRate(target, categories, review) {
    try {
      await saveRating({ mediaType, mediaId: target.id, categories, media: target, review });
      setUserRating({ ...categories, media_id: target.id, review });
      setDetailMessage('Rating saved!');
    } catch (err) {
      setDetailMessage(err.message);
    }
  }

  async function handleWatchlist(target) {
    setIsAddingWatchlist(true);
    setDetailMessage('');
    try {
      const saved = await addWatchlistItem({ mediaType, mediaId: target.id, media: target });
      setWatchlistEntry({ id: saved.id, status: saved.status });
      setDetailMessage(`"${target.title}" added to your watchlist.`);
    } catch (err) {
      setDetailMessage(err.message);
    } finally {
      setIsAddingWatchlist(false);
    }
  }

  function handleStatusChange(target, entry, nextStatus) {
    setWatchlistEntry((current) => ({ ...current, status: nextStatus }));
    if (!entry?.id) return;
    updateWatchlistStatus(entry.id, nextStatus).catch(() => {
      setWatchlistEntry(entry);
    });
  }

  async function handleAddToLibrary(book) {
    setDetailMessage('');
    setIsAddingWatchlist(true);
    try {
      await addWatchlistItem({ mediaType: 'book', mediaId: book.id, status: 'plan_to_read', media: book });
      setIsInLibrary(true);
      setDetailMessage('Added to your Library.');
    } catch (err) {
      if (/already in watchlist/i.test(err.message)) {
        setIsInLibrary(true);
        setDetailMessage('This book is already in your Library.');
      } else {
        setDetailMessage(err.message);
      }
    } finally {
      setIsAddingWatchlist(false);
    }
  }

  if (!item) return null;

  if (mediaType === 'book') {
    return (
      <BookDetailsModal
        book={item}
        onClose={goBack}
        onAddToLibrary={handleAddToLibrary}
        isInLibrary={isInLibrary}
        isAddingToLibrary={isAddingWatchlist}
        onRate={handleRate}
        userRating={userRating}
        detailMessage={detailMessage}
        allowActions={!browseOnly}
        browseOnlyMessage="Fallback catalog mode is browse-only."
      />
    );
  }

  return (
    <MediaDetailsModal
      item={item}
      mediaType={mediaType}
      onClose={goBack}
      onRate={browseOnly ? undefined : handleRate}
      onWatchlist={browseOnly ? undefined : handleWatchlist}
      watchlistEntry={watchlistEntry}
      onStatusChange={browseOnly ? undefined : handleStatusChange}
      userRating={userRating}
      isAddingWatchlist={isAddingWatchlist}
      detailMessage={detailMessage}
      allowActions={!browseOnly}
      browseOnlyMessage="Fallback catalog mode is browse-only."
      autoPlay={playImmediately}
      initialSeason={initialSeason}
      initialEpisode={initialEpisode}
    />
  );
}
